be9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Artículo 46. -","tipo_articulo":"ordinario","titulo_nombre":"De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"De las responsabilidades y sanciones","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":45,"contenido_md5":"e6c209a8fe214fbd4c50ec782d930483"},{"id":"eb54016a-83de-4963-9f51-d82c9085935e","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Artículo 47. -","tipo_articulo":"ordinario","titulo_nombre":"De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":46,"contenido_md5":"8526b837c500a5d31483ebc1a5fdcbc5"},{"id":"b702e834-7c0d-44c9-b10a-29fc5a1568dd","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Artículo   48. -","tipo_articulo":"ordinario","titulo_nombre":"De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":47,"contenido_md5":"99913443a0bfbaa73cb23ca5ffa17261"},{"id":"3038ee1d-0b43-4afe-964d-e19dd42abec2","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Artículo 49. -","tipo_articulo":"ordinario","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":48,"contenido_md5":"307ee57b1b33c7cb4edd750f7aa0ef69"},{"id":"b3f88725-e252-42e6-9a9f-dd5531e3c4db","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Transitorio PRIMERO.","tipo_articulo":"transitorio","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":49,"contenido_md5":"e6d980d06571844aa00d939c8080a793"},{"id":"5c4ca336-bbb8-476f-922e-61478937aff9","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Transitorio SEGUNDO.","tipo_articulo":"transitorio","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":50,"contenido_md5":"a4409f2bf752eb99da0ba188bc289be0"},{"id":"49e5464c-2449-4ee2-b921-3e921b93b064","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Transitorio TERCERO.","tipo_articulo":"transitorio","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":51,"contenido_md5":"6037f654f8ee93791a5994f8d4dd4f8c"},{"id":"0486ecaa-9211-4c17-baf4-afe734980d7b","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Transitorio CUARTO.","tipo_articulo":"transitorio","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":52,"contenido_md5":"5506167533f1040e4f5d134928479db9"},{"id":"76261bbe-2b83-4901-8754-a75329430901","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Transitorio QUINTO.","tipo_articulo":"transitorio","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":53,"contenido_md5":"de40455f206e4727c0769ee271fb8619"},{"id":"938dab1f-c72e-4087-9f2d-c2aadc9576da","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Transitorio SEXTO.","tipo_articulo":"transitorio","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":54,"contenido_md5":"3f8c2dd10aa6e71f778e71184e0a783e"},{"id":"2479fdd9-8d5f-43e7-bc0b-3b5b243b9729","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","identificador":"Transitorio SÉPTIMO.","tipo_articulo":"transitorio","titulo_nombre":"De la aplicación supletoria","capitulo_nombre":"De la gradualidad","seccion_nombre":"Del Distintivo Nacional de Economía Circular","orden":55,"contenido_md5":"624c41d9ffeed62fdb4958ff7cb42523"}],"after":[{"identificador":"Preámbulo","tipo_articulo":"preambulo","contenido":"DECRETO por el que se expide la Ley General de Economía Circular y, se reforman y adicionan diversas disposiciones de la Ley General del Equilibrio Ecológico y la Protección al Ambiente y de la Ley General para la Prevención y Gestión Integral de los Residuos.\nAl margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República.\nCLAUDIA SHEINBAUM PARDO, Presidenta de los Estados Unidos Mexicanos, a sus habitantes sabed:\nQue el Honorable Congreso de la Unión, se ha servido dirigirme el siguiente\nDECRETO\n\n\"EL CONGRESO GENERAL DE LOS ESTADOS UNIDOS MEXICANOS, DECRETA:\nSE EXPIDE LA LEY GENERAL DE ECONOMÍA CIRCULAR Y, SE REFORMAN Y ADICIONAN DIVERSAS DISPOSICIONES DE LA LEY GENERAL DEL EQUILIBRIO ECOLÓGICO Y LA PROTECCIÓN AL AMBIENTE Y DE LA LEY GENERAL PARA LA PREVENCIÓN Y GESTIÓN INTEGRAL DE LOS RESIDUOS\nArtículo Primero.- Se expide la Ley General de Economía Circular, para quedar como sigue:\nLEY GENERAL DE ECONOMÍA CIRCULAR","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"0d5667b7-1cf4-4901-abdf-b2589ba19283","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":0},{"identificador":"Artículo 1","tipo_articulo":"ordinario","contenido":"La presente Ley es de orden público, interés social y de observancia general en el territorio nacional y es reglamentaria de los artículos 4o., párrafo sexto; 25, párrafos primero y séptimo, y 73, fracción XXIX-G, de la Constitución Política de los Estados Unidos Mexicanos.\nLa Ley tiene por objeto cuidar y conservar al medio ambiente a través de políticas y mecanismos en materia de Economía Circular para incrementar la vida útil de los productos; minimizar, recuperar, aprovechar y valorizar los residuos, así como establecer la concurrencia de atribuciones entre la Federación, entidades federativas, municipios y demarcaciones territoriales de la Ciudad de México.","titulo_nombre":"Título Primero Disposiciones Generales","capitulo_nombre":"Capítulo Primero Del objeto y ámbito de aplicación","seccion_nombre":null,"id":"237f83a7-23c6-40a9-ac67-a6ba0db9691e","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":1},{"identificador":"Artículo 2","tipo_articulo":"ordinario","contenido":"Son objetivos de la presente Ley, los siguientes:\nI. Impulsar y definir las políticas públicas en materia de Economía Circular con base en los principios, criterios y definiciones de esta Ley;\nII. Instituir e impulsar los mecanismos directos e indirectos de circularidad que sean ambiental, técnica y económicamente viables que deben aplicarse a los materiales, los residuos y las categorías de productos;\nIII. Establecer, los acuerdos generales de implementación de la REP con los que se obliga, por sector industrial, comercial o de servicios, o por Producto, a obtener la inscripción de la Gestión Circular en el Registro de Economía Circular y cumplir los términos y condiciones de dicha gestión, con la participación del sector productivo;\nIV. Fijar la responsabilidad compartida en materia de circularidad de otros agentes económicos, consumidores y entes públicos, la cual es complementaria a la REP;\nV. Disponer que para el cumplimiento de las disposiciones de circularidad y en atención al principio de gradualidad deben considerarse las diferencias entre los sectores, los productos y las personas productoras mediante la emisión de acuerdos generales de implementación de la REP, la definición de metas, la aplicación de mecanismos directos e indirectos de circularidad, así como la suscripción de convenios y la ejecución de las demás medidas que establezca esta Ley;\nVI. Fomentar e impulsar la Economía Circular a través de instrumentos económicos y de distintivos de comercialización que establezca la normativa aplicable;\nVII. Establecer el procedimiento para la auditoría ambiental voluntaria, así como las medidas de control y vigilancia, y\nVIII. Fomentar, impulsar e implementar la estrategia nacional y las políticas en la materia de Economía Circular; la educación y cultura de la circularidad, la innovación tecnológica y la infraestructura circular; el acopio de productos susceptibles de reciclaje; la reducción del desperdicio de alimentos y el incremento en su aprovechamiento, y la cooperación internacional.","titulo_nombre":"Título Primero Disposiciones Generales","capitulo_nombre":"Capítulo Primero Del objeto y ámbito de aplicación","seccion_nombre":null,"id":"bd22896e-45f2-4894-bded-e568000e9c11","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":2},{"identificador":"Artículo 3","tipo_articulo":"ordinario","contenido":"Para efectos de esta Ley se entiende por:\nI. Actividad Económica: Conjunto de acciones de Producción realizadas por una persona física o moral, productora o importadora;\nII. Análisis de Ciclo de Vida: Herramienta de análisis usada para evaluar el Ciclo de Vida, en los términos de los acuerdos generales de implementación de la REP;\nIII. Aprovechamiento Circular: Acciones cuyo objetivo es mantener o potenciar el valor económico de los materiales y productos, o recuperar el valor económico de los residuos, mediante la aplicación de mecanismos directos e indirectos de circularidad, conforme a los principios de Economía Circular;\nIV. Cadena de Valor: Actividades que permiten la integración de materiales, productos o de los residuos para su Aprovechamiento Circular, ya sea para el mismo proceso que lo generó o en otros;\nV. Ciclo de Vida: Etapas consecutivas e interrelacionadas con los materiales, productos o residuos, desde la extracción, Producción, vida útil, gestión integral de residuos, Aprovechamiento Circular o, en su caso, disposición final;\nVI. Consumo Responsable: Adquisición, uso y disposición del Producto de manera informada de los efectos ambientales y sociales que involucran dichos bienes y servicios;\nVII. Diseño Circular: Diseño del Producto que considere la Huella Ambiental con enfoque integral y que incorpora principios y mecanismos directos e indirectos de circularidad en su Ciclo de Vida;\nVIII. Economía Circular: Modelo económico de Producción y Consumo sostenible que incluye soluciones sistémicas para el desarrollo económico, que disminuyen el impacto ambiental mediante ciclos técnicos y biológicos que permiten la permanencia y reintegración sustentable de los materiales de los productos a la economía, el cual tiene como principios rectores la eliminación de residuos y la contaminación, mantener productos y materiales en uso, así como regenerar los sistemas naturales;\nIX. Encadenamiento Sustentable: Vínculos entre personas compradoras, entre vendedoras y entre unas y otras, en unidades productivas o sectores económicos, que involucran el intercambio de materiales, productos y residuos bajo criterios de Economía Circular, conforme a los objetivos y criterios del Programa Nacional, y como Mecanismo Indirecto de Circularidad para cumplimiento de la REP;\nX. Gestión Circular: Conjunto de estrategias aplicadas a lo largo del Ciclo de Vida de materiales, productos o residuos, incluido el Diseño Circular, para lograr la menor Huella Ambiental y el máximo Aprovechamiento Circular, mediante la aplicación de mecanismos directos o indirectos de circularidad;\nXI. Huella Ambiental: Impacto ambiental medible a través de indicadores de Economía Circular que se produce por:\na) Las actividades realizadas para generar un Producto, y\nb) Las características del Producto que permitan maximizar su vida útil y el Aprovechamiento Circular como residuo;\nXII. Indicador de Economía Circular: Parámetro cuantitativo que permite medir el grado de circularidad de un Producto, proceso o sistema, mediante los indicadores siguientes:\na) Índice de materiales: La relación entre la masa de materiales obtenidos de mecanismos de circularidad y la masa total de materiales utilizados en la Producción;\nb) Huella de carbono: Cuantificación, a lo largo del Ciclo de Vida de un Producto, del valor neto de las emisiones de gases de efecto invernadero, y de carbono negro en la atmósfera, así como de las remociones correspondientes;\nc) Huella hídrica: Cuantificación del uso eficiente y sustentable del agua, y\nd) Índice de aprovechamiento energético: Cuantificación de la sustitución calorífica por fuentes acorde a los principios de Economía Circular;\n\nXIII. Instrumento Económico: Mecanismos normativos o administrativos de carácter fiscal, aduanal, financiero o de mercado, que se expida por la autoridad competente en los términos de las disposiciones jurídicas aplicables, y mediante los cuales las personas asumen los beneficios y costos ambientales que generen sus actividades económicas, que les incentiven a realizar mecanismos directos e indirectos de circularidad;\nXIV. Ley: Ley General de Economía Circular;\nXV. LGPGIR: Ley General para la Prevención y Gestión Integral de los Residuos;\nXVI. Material Virgen: Materias primas extraídas directamente de fuentes naturales, sin previamente haber sido utilizadas o procesadas en un ciclo productivo;\nXVII. Materia Prima Secundaria: Material, sustancia u objeto que después de su Producción, utilización o consumo conserva propiedades que permiten su procesamiento, independientemente que derive de la Gestión Circular de un Producto o de un residuo;\nXVIII. Mecanismo Directo de Circularidad: Aquel que aplica principios, criterios, medidas, instrumentos, procesos, estrategias o acciones de circularidad al Ciclo de Vida de productos, materiales y residuos, las cuales comprenden:\na) Para categorías de productos y para materiales: reúso, reducción, rediseño y reacondicionamiento;\nb) Para residuos: recuperación, tratamiento, reciclaje y valorización, y\nc) Para ambas etapas: Diseño Circular, clasificación, reparación, remanufactura, reutilización, aprovechamiento y reciclaje cuando aplique;\nXIX. Mecanismo Indirecto de Circularidad: Aquel que aplica principios, acciones, procesos o estrategias de circularidad para el cumplimiento de la Gestión Circular inscrito en el Registro, las cuales comprenden el Encadenamiento Sustentable y la compensación ambiental;\nXX. Modelo de Complementariedad: Aquel donde los sectores productivos aprovechan los materiales de una empresa o sector como Materia Prima Secundaria o residuos en los procesos de la otra empresa o sector para implementar, entre estos sectores, un eficiente y óptimo Encadenamiento Sustentable;\nXXI. Modelo de Servicio: Estrategia empresarial basada en la transición de un modelo de economía lineal a un modelo de Economía Circular, orientado a maximizar la vida útil del Producto;\nXXII. Organismo Coordinador: Ente asociativo de carácter público, privado o mixto, constituido legalmente, cuya finalidad es fomentar en la Actividad Económica los principios y criterios de Economía Circular previstos en la legislación vigente, con representación para promover y defender las actividades de las personas productoras, que manifiesten su incorporación, y que puede ser constituido por sectores de la industria, el comercio o de servicios, y corresponsable de la Gestión Circular en el sector productivo que represente, y registrado por la Secretaría;\nXXIII. Persona recicladora de base o pepenadora: Persona que, de forma independiente o colectiva, realiza la recolección, separación manual, comercialización y reciclaje de materias primas secundarias;\nXXIV. Plataforma Nacional: Plataforma del Sistema Nacional de Información Pública de Economía Circular;\nXXV. Producción: La acción de una persona física o moral que fabrica o importa un Producto;\nXXVI. Producto: Bien físico que se fabrica o importa o servicio que se presta; que cuenta con valor económico, y que se genera como resultado de un proceso de actividades en las que se incluye la transformación de materiales;\nXXVII. Programa Nacional: Programa Nacional de Economía Circular;\nXXVIII. Reciclaje Inclusivo: Modelos de gestión integral que reconocen el trabajo de las personas recicladoras de base o pepenadoras y que promueven su inclusión en términos de las disposiciones legales laborales o sociales aplicables;\nXXIX. Registro o Registro de Economía Circular: El registro público instalado en la Plataforma Nacional con la función de inscribir en este la Gestión Circular;\nXXX. Reglamento: Reglamento de la Ley General de Economía Circular;\nXXXI. Responsabilidad Extendida del Productor o REP: Medio por el cual la persona productora o importadora es responsable ambientalmente de su Producto en su Ciclo de Vida, en términos de la Gestión Circular que inscriba ante la Secretaría. La REP y la responsabilidad compartida prevista en la LGPGIR, así como aquellas que corresponden al consumidor y a la autoridad competente pueden ser aplicables de manera complementaria y no se excluyen entre ellas;\nXXXII. Secretaría: Secretaría de Medio Ambiente y Recursos Naturales, y\nXXXIII. Sistema: Sistema Nacional de Economía Circular.","titulo_nombre":"Título Primero Disposiciones Generales","capitulo_nombre":"Capítulo Primero Del objeto y ámbito de aplicación","seccion_nombre":null,"id":"a56b02ce-e9e0-45ab-a09d-58390589717a","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":3},{"identificador":"Artículo 4","tipo_articulo":"ordinario","contenido":"La Federación tiene a su cargo el diseño y la conducción de la política nacional en materia de Economía Circular.\nEn la planeación y ejecución de las acciones para cuidar y conservar al medio ambiente, las dependencias y entidades de la Administración Pública Federal, conforme a sus respectivas esferas de competencia, así como en el ejercicio de las atribuciones, deben observar los siguientes enfoques de criterios y principios:\nA. Enfoques de criterios de Economía Circular:\nI. Fomentar e impulsar la Economía Circular que permita un desarrollo económico sustentable de carácter restaurativo y regenerativo;\nII. Fomentar la integración de procesos productivos que extiendan la vida útil del Producto y sus componentes, con lo cual se optimice su uso en cada etapa del Ciclo de Vida;\nIII. Incentivar los mecanismos directos e indirectos de circularidad, así como las estrategias circulares en los sectores productivos y de servicios, que faciliten el acceso a productos entre particulares sin que necesariamente se transfieran la propiedad;\nIV. Incentivar hábitos de consumo social y ambientalmente responsable, que incluya la separación de residuos;\nV. Promover el uso eficiente y prolongado del Producto, a fin de preservar y potenciar su valor económico, así como recuperar el valor de los residuos;\nVI. Fomentar la sustentabilidad de la Actividad Económica que minimice los posibles impactos al ambiente y se alinee con los principios de la Economía Circular;\nVII. Impulsar y fomentar que la generación del Producto se realice con la adopción de los criterios y principios previstos en la presente Ley;\nVIII. Promover la Gestión Circular y la creación de cadenas de valor que integren distintos componentes con fomento en el uso de materias primas secundarias y residuos en sus procesos de generación, importación, exportación, transporte, distribución, comercialización y consumo del Producto, con base en esquemas que permitan el máximo Aprovechamiento Circular y la recuperación de los residuos a partir de su valorización;\nIX. Impulsar y Fomentar la Economía Circular entre la población y los sectores productivos, a efecto de que se integren los principios y Gestión Circular en el desarrollo de la infraestructura y tecnología, así como garantizar el acceso a la información en la materia;\nX. Fomentar el desarrollo de sectores productivos mediante la Economía Circular;\nXI. Fomentar e incentivar las estrategias y actividades destinadas al desarrollo de la Economía Circular en los sectores productivos de bienes y servicios;\nXII. Evitar la obsolescencia de los productos y su utilización como objetivo comercial o financiero, en términos del acuerdo general de implementación de la REP correspondiente, y\nXIII. Fomentar el uso de materias primas secundarias en lugar de materiales vírgenes que ofrezcan las mismas características, cuando sea ambiental, técnica y económicamente viable, y\n\nB. Principios de Economía Circular:\nI. Atemporal: Permite a los productos trascender en el tiempo y ser vigentes y útiles el mayor tiempo posible, mediante la Gestión Circular y mecanismos directos e indirectos de circularidad, el uso de materiales adecuados, manufactura de calidad y modelos de diseño y consumo que eviten promover su reemplazo periódico o prematuro, conforme a los principios de la Economía Circular;\nII. Cautela o precaución: Acciones en los casos que haya riesgo de daño grave o irreversible al medio ambiente, aún sin tener certeza científica sobre los impactos que genera una Actividad Económica;\nIII. Circularidad: Optimizar la Gestión y el Aprovechamiento Circular de los materiales y del Producto, durante todo el Ciclo de Vida;\nIV. Gradualidad: Ajuste progresivo de los mecanismos directos e indirectos de circularidad mediante la emisión de acuerdos generales de implementación de la REP, la definición de metas, la suscripción de convenios y la ejecución de otras medidas previstas en el artículo 47 de esta Ley;\nV. Innovador: Incorporación continua de tecnologías, energías renovables y mejoras productivas con beneficios ambientales, económicos y de bienestar social;\nVI. Integralidad: Articulación de políticas públicas con las actividades de los sectores y con objetivos del desarrollo para satisfacer las necesidades de la población, con criterios ecológicos, sociales y económicos de manera transversal;\nVII. Jerarquización: Orden de prioridad de los mecanismos directos e indirectos de circularidad en la gestión de materiales, productos y residuos, para lograr los mejores resultados ambientales en conjunto, con la prelación y los fines siguientes:\na) Que los materiales se mantengan el mayor tiempo posible como Producto o Materia Prima Secundaria;\nb) Que los productos incorporen materiales reciclados, reciclables o ambos;\nc) Que los residuos se reincorporen mediante la recuperación de su valor o del contenido energético de los materiales que los componen, y\nd) Que los residuos solo se depositen o confinen en disposición final cuando técnica y económicamente no sea viable ningún tipo de aprovechamiento y valorización;\nVIII. Modular: Enfocado a que los productos sean separables en componentes o módulos que puedan ser reparados, actualizados o reutilizados de manera independiente, cuando sea viable ambiental, técnica y económicamente;\nIX. Progresividad: Impulsar la implementación gradual de la Economía Circular, de tal forma que siempre se avance hacia su fortalecimiento y no se realicen acciones que impliquen su retroceso;\nX. Reparabilidad: Garantiza que los productos sean concebidos, fabricados, distribuidos, importados y comercializados, mediante la provisión de información clara y accesible sobre la posibilidad de repararlos; la disponibilidad de refacciones, herramientas, piezas de repuesto y de lugares donde pueden repararse;\nXI. Responsabilidad Extendida del Productor: Obligación que se aplica de manera complementaria y no excluyente a otras obligaciones de los entes públicos y de los particulares en los términos que define esta Ley;\nXII. Sistémico: Consideración de generación de productos analizados en su conjunto, así como en correlación con su entorno, para identificar las implicaciones ecológicas, sociales y económicas de sus procesos de elaboración, distribución, consumo y permanencia dentro del ambiente, y maximizar la gestión y el uso de materiales, así como las acciones de recuperación de los residuos a partir de su valorización;\nXIII. Sustentabilidad: Uso de los recursos naturales que permita, simultáneamente, preservar el equilibrio ecológico, contribuir a la regeneración de los sistemas naturales e incrementar el bienestar de las personas mediante la satisfacción de sus necesidades, sin comprometer las de las generaciones futuras;\nXIV. Transversalidad: Coordinación y colaboración entre distintos órdenes de gobierno y sectores académico, social y privado, a fin de alcanzar objetivos en Economía Circular, y\nXV. Trazabilidad: Información en toda la cadena de manejo de un determinado Producto o material, con la finalidad de contar con un registro de los datos de los flujos del Ciclo de Vida, conforme a la normativa aplicable.","titulo_nombre":"Título Primero Disposiciones Generales","capitulo_nombre":"Capítulo Segundo Criterios y principios de Economía Circular","seccion_nombre":null,"id":"ad663c0d-29b8-48b8-98db-afdd845a19f6","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":4},{"identificador":"Artículo 5","tipo_articulo":"ordinario","contenido":"El Sistema Nacional de Economía Circular tiene como objetivo la coordinación entre los tres órdenes de gobierno para el cumplimiento de los fines de la Economía Circular de acuerdo con los criterios y principios establecidos en esta Ley. La conducción del Sistema está a cargo de la Secretaría.\nEl Sistema se integra con los entes públicos siguientes:\nI. La Secretaría, quien preside el Sistema;\nII. La Secretaría de Economía;\nIII. La Secretaría de Hacienda y Crédito Público;\nIV. La Secretaría de Energía;\nV. La Secretaría de Desarrollo Agrario, Territorial y Urbano;\nVI. La Secretaría de Infraestructura, Comunicaciones y Transportes;\nVII. La Secretaría de Educación Pública;\nVIII. La Secretaría de Ciencia, Humanidades, Tecnología e Innovación, y\nIX. Cada entidad federativa, representada por conducto de la persona titular de la Secretaría o institución con atribuciones en materia de medio ambiente y cuidado de los recursos naturales.\nA las sesiones deben concurrir las personas titulares de los referidos entes públicos, quienes pueden designar como suplentes a las personas servidoras públicas con nivel mínimo de dirección general o un equivalente.\nEl nombramiento como integrantes del Sistema y el de suplente son de carácter honorífico; por el desempeño de estos cargos no percibirán emolumento o compensación económica alguna.\nEl Sistema Nacional de Economía Circular cuenta con una secretaría técnica, la cual está a cargo de la subsecretaría competente de la Secretaría.\nLos municipios y las demarcaciones territoriales de la Ciudad de México pueden asistir a las sesiones, cuando así lo consideren la Presidencia del Sistema o por acuerdo de sus integrantes.\nA las sesiones del Sistema se pueden convocar a los sectores público, social y privado, cuando así lo soliciten o sean convocados.\nEl Sistema debe expedir las reglas para su operación y funcionamiento, conforme a las cuales se llevan a cabo sus sesiones y las convocatorias a estas.","titulo_nombre":"Título Segundo Sistema Nacional de Economía Circular y distribución de competencias","capitulo_nombre":"Capítulo Primero Del Sistema Nacional de Economía Circular","seccion_nombre":null,"id":"b74d3c9e-85fd-4cfa-875d-870e23867c43","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":5},{"identificador":"Artículo 6","tipo_articulo":"ordinario","contenido":"La Federación, en el ámbito administrativo, a través de la Secretaría tiene las atribuciones siguientes:\n\nI. Formular y conducir la política nacional en materia de Economía Circular, en coordinación con las instancias que correspondan, así como elaborar el Programa Nacional correspondiente;\nII. Elaborar el Programa Nacional de Economía Circular que tendrá el carácter de especial y de cumplimiento obligatorio de conformidad con la Ley de Planeación;\nIII. Expedir la norma oficial mexicana de Economía Circular, los correspondientes estándares y las demás disposiciones generales con carácter técnico y, conforme a los tratados internacionales de los que México es parte, con la participación:\na) Que competa a la Secretaría de Economía, y\nb) De la sociedad, en términos de la Ley de Planeación;\nIV. Coordinar, con la participación de las dependencias que sean competentes en la materia, la implementación de modelos de Economía Circular en la Cadena de Valor, así como fomentar la creación de organismos coordinadores, el Encadenamiento Sustentable, el Reciclaje Inclusivo y espacios para la obtención de Materia Prima Secundaria;\nV. Celebrar convenios en materia de Economía Circular con las entidades federativas, los municipios o las demarcaciones territoriales de la Ciudad de México, así como con los sectores público, privado y social;\nVI. Integrar y operar la Plataforma Nacional, de conformidad con lo previsto en esta Ley y en el Reglamento;\nVII. Coordinar, con las dependencias de la Administración Pública Federal competentes, acciones y relaciones internacionales para promover y fomentar el cumplimiento de los principios y objetivos establecidos en la presente Ley;\nVIII. Impulsar, en coordinación con las secretarías del ramo en materia de economía, y de ciencia, humanidades, tecnología e innovación, las acciones de investigación, desarrollo, diseño e innovación de tecnologías, equipos, materiales, sistemas, técnicas y procesos productivos para transitar hacia una Economía Circular;\nIX. Diseñar y promover, con la participación activa de los sectores productivos, a fin de proponer a la Secretaría de Hacienda y Crédito Público, el establecimiento y aplicación de beneficios a través de instrumentos económicos, que tengan por objeto fomentar la Economía Circular;\nX. Expedir acuerdos generales de implementación de la REP que, con base en el principio de gradualidad, establezcan los mecanismos directos e indirectos de circularidad aplicables, la definición de metas, así como la posibilidad de suscripción de convenios de concertación que establecen las leyes aplicables, y las demás medidas en términos de la normativa ambiental;\nXI. Establecer o autorizar mecanismos indirectos de circularidad como formas alternativas de cumplimiento;\nXII. Emitir disposiciones normativas orientadas a incentivar la generación de actividades económicas circulares, la fabricación de productos para el Aprovechamiento Circular, y la minimización gradual de aquellos de difícil aprovechamiento, cuando ello resulte ambiental, técnica y económicamente viable conforme a las características del sector correspondiente;\nXIII. Fomentar que en los procesos se utilicen materias primas secundarias y se recuperen, aprovechen y valoricen residuos cuando ello resulte ambiental, técnica y económicamente viable;\nXIV. Verificar el cumplimiento de la normativa en las materias de su competencia e imponer las medidas preventivas, de cautela, correctivas y sancionatorias que, en su caso, correspondan;\nXV. Brindar asesoría y asistencia técnica a las entidades federativas, municipios y demarcaciones territoriales de la Ciudad de México en la integración, formulación e implementación de proyectos y programas de fomento y desarrollo en materia de Economía Circular, conforme a los convenios de coordinación que, en su caso, se celebren;\nXVI. Promover un Modelo de Servicio que facilite la generación de negocios que se basen en el acceso del Producto sin que necesariamente los consumidores o usuarios adquieran la propiedad de estos, alineados con los principios y criterios de Economía Circular, así como fortalecer los servicios ya existentes, incluso los que adopten modelos de complementariedad, y\nXVII. Las demás que se establezcan en esta Ley, en el Reglamento y en otros ordenamientos jurídicos que resulten aplicables.","titulo_nombre":"Título Segundo Sistema Nacional de Economía Circular y distribución de competencias","capitulo_nombre":"Capítulo Segundo De la distribución de competencias","seccion_nombre":null,"id":"0ce993b1-b464-45a2-9ffc-5330f5061ea4","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":6},{"identificador":"Artículo 7","tipo_articulo":"ordinario","contenido":"Las dependencias y entidades de la Administración Pública Federal, que ejerzan atribuciones que les confieran otros ordenamientos, cuyas disposiciones se relacionen con el objeto de la presente Ley, deben ajustar su ejercicio a las disposiciones previstas en esta y a la normativa que derive de esta, incluidas las normas oficiales mexicanas, estándares y demás disposiciones administrativas de carácter general.\nLas dependencias y entidades de la Administración Pública Federal, en el ámbito de sus atribuciones y de manera progresiva, implementarán programas internos de Economía Circular, para tal efecto, la Secretaría debe emitir los lineamientos correspondientes.","titulo_nombre":"Título Segundo Sistema Nacional de Economía Circular y distribución de competencias","capitulo_nombre":"Capítulo Segundo De la distribución de competencias","seccion_nombre":null,"id":"814c8b93-5000-4eab-8ccc-15b83bb1a2ae","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":7},{"identificador":"Artículo 8","tipo_articulo":"ordinario","contenido":"Las entidades federativas tienen las atribuciones siguientes:\nI. Implementar las políticas estatales de Economía Circular alineadas con lo establecido en el Programa Nacional, la Ley y el Reglamento;\nII. Impulsar y fomentar la investigación, desarrollo, e innovación de tecnologías, equipos, materiales, sistemas y procesos que tengan como fin fomentar la Economía Circular;\nIII. Promover la participación de los sectores privado, social, académico y de investigación, en el diseño e instrumentación de acciones para fomentar la Economía Circular, conforme a la presente Ley y el Reglamento;\nIV. Promover, a través de las autoridades competentes, la educación y la capacitación continua, para fortalecer la cultura de corresponsabilidad social en la generación y consumo de productos que cumplan con criterios de Economía Circular;\nV. Reportar y actualizar información sobre Economía Circular a la Federación, conforme a lo establecido en el Reglamento;\nVI. Celebrar convenios con las autoridades competentes de los tres órdenes de gobierno, así como con los sectores público, privado y social, para llevar a cabo acciones que coadyuven a los objetivos de esta Ley;\nVII. Evaluar, en términos de los convenios que se celebren con la Secretaría, la implementación de la Economía Circular en los sectores productivos de bienes y de prestación de servicios que estén establecidos dentro de su territorio, conforme al Programa Nacional;\nVIII. Impulsar que la Actividad Económica se efectúe conforme a los principios de Economía Circular previstos en la presente Ley;\nIX. Fomentar prácticas de economía local, colaborativa y solidaria;\nX. Fomentar y promover el emprendimiento con base en los principios de Economía Circular establecidos en la presente Ley;\nXI. Solicitar asistencia técnica a la Secretaría de acuerdo con el ámbito competencial de estas, y\nXII. Las demás que se prevén en esta Ley y en otros ordenamientos que resulten aplicables.","titulo_nombre":"Título Segundo Sistema Nacional de Economía Circular y distribución de competencias","capitulo_nombre":"Capítulo Segundo De la distribución de competencias","seccion_nombre":null,"id":"c295f78e-38ab-408e-9155-061684fe0586","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":8},{"identificador":"Artículo 9","tipo_articulo":"ordinario","contenido":"Cada municipio, en el ámbito de su competencia, tiene las siguientes atribuciones:\nI. Aplicar, en el ejercicio de funciones de manejo integral de residuos sólidos urbanos, las disposiciones previstas en la LGPGIR que impliquen la ejecución de los principios y criterios de Economía Circular que establece la presente Ley;\nII. Elaborar y presentar programas de fomento y desarrollo en materia de Economía Circular, con contenidos alineados con el Programa Nacional;\nIII. Participar, en coordinación con las entidades federativas, en la promoción de modelos de Economía Circular;\nIV. Promover y desarrollar proyectos en materia de Economía Circular para la mejora continua de las capacidades laborales y productivas de las personas trabajadoras;\nV. Impulsar ferias, exposiciones, congresos, eventos y actividades similares que promuevan la economía local, sostenible, colaborativa, comunitaria y solidaria, así como el emprendimiento con base en los principios de Economía Circular establecidos en la presente Ley;\nVI. Brindar a la población, información y capacitación, así como desarrollar campañas, en materia de Economía Circular, de acuerdo con los criterios y principios de la presente Ley, y\nVII. Las demás que se prevén en esta Ley y en otros ordenamientos que resulten aplicables.\nCorresponde al Gobierno de la Ciudad de México, ejercer las facultades y obligaciones que este ordenamiento confiere a las entidades federativas y a los municipios respectivamente.","titulo_nombre":"Título Segundo Sistema Nacional de Economía Circular y distribución de competencias","capitulo_nombre":"Capítulo Segundo De la distribución de competencias","seccion_nombre":null,"id":"fa32e95b-49b5-4f8b-9f04-64206ad987ef","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":9},{"identificador":"Artículo 10","tipo_articulo":"ordinario","contenido":"La Secretaría, mediante acuerdos generales de implementación de la REP determinará mecanismos para la implementación gradual de las obligaciones contenidas en esta Ley, por sector productivo, Producto, o ambos. El sector productivo debe ser convocado a participar en la elaboración del proyecto del acuerdo general correspondiente.\nLa Secretaría de Economía emitirá opinión previa sobre los acuerdos generales de implementación de la REP en el ámbito de su competencia. En los casos que proceda, los anunciará, notificará o consultará, según corresponda, en términos de los acuerdos internacionales en materia económica.\nAsimismo, debe requerir al sector productivo, a la persona productora y, en su caso, a los organismos coordinadores, a las confederaciones nacionales, o las cámaras nacionales, información para la elaboración de acuerdos generales de implementación.\nLas personas productoras e importadoras y, en su caso, los organismos coordinadores:\nI. Están sujetas al cumplimiento de las disposiciones de los acuerdos generales de implementación de la REP, y\nII. Pueden celebrar convenios de concertación con la Secretaría en términos del artículo 48 de esta Ley, así como de auditoría ambiental voluntaria con la Procuraduría Federal de Protección al Ambiente conforme al artículo 35 de esta Ley.\nLas autoridades competentes podrán otorgar estímulos fiscales en términos de la normativa aplicable.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":null,"seccion_nombre":null,"id":"edd8657f-d652-4113-9559-d18ace6db06a","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":10},{"identificador":"Artículo 11","tipo_articulo":"ordinario","contenido":"La Gestión Circular debe incorporar integralmente los aspectos ambientales, funcionales, económicos y sociales a lo largo del Ciclo de Vida de materiales, productos y residuos.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Primero De la Gestión Circular y su registro","seccion_nombre":null,"id":"5ec9ee3a-909c-4efa-b590-cae868d6b1c1","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":11},{"identificador":"Artículo 12","tipo_articulo":"ordinario","contenido":"Cuando la Secretaría publique en el Diario Oficial de la Federación un acuerdo general de implementación de la REP y, todas las personas productoras e importadoras o, en su caso, el Organismo Coordinador, comprendidos en el acuerdo, tienen la obligación de elaborar la Gestión Circular y solicitar su inscripción en el Registro, en los plazos que en el propio acuerdo se establezcan.\nEl acuerdo general de implementación de la REP debe prever las actividades que correspondan al sector o categoría del Producto que regule, para que cada persona productora o importadora pueda ejecutar los mecanismos directos o indirectos de circularidad respectivos, cuando sean ambiental, técnica y económicamente viables; también debe establecer metas que cada persona productora o importadora debe cumplir en los términos de la autorización de inscripción al Registro o en el convenio que, en su caso, se suscriba, así como los indicadores y metodologías para medirlas.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Primero De la Gestión Circular y su registro","seccion_nombre":null,"id":"7ae39ee3-715b-4632-8db4-ec3c3d7823d3","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":12},{"identificador":"Artículo 13","tipo_articulo":"ordinario","contenido":"Corresponde a la Secretaría analizar y autorizar la inscripción de la Gestión Circular. Para el análisis de la Gestión Circular, la Secretaría puede formular observaciones o requerir información. En el acto administrativo de registro, la Secretaría debe:\nI. Evaluar la Gestión Circular y, en estos casos, puede:\na) Condicionar la inscripción con base en el acuerdo general de implementación de la REP correspondientes, así como en los convenios de concertación que, en su caso, se suscriban;\nb) Sujetar la Gestión Circular a esquemas y metas de gradualidad de cumplimiento, en términos del artículo 48 de esta Ley y del acuerdo general de implementación de la REP y de los convenios de concertación suscritos correspondientes, y\nc) Considerar si el Producto cuenta o no con un plan de manejo en términos de la LGPGIR. En caso de contar con dicho plan la Secretaría debe considerar las autorizaciones o permisos ya existentes y reconocer la información que obra en sus archivos;\nII. Autorizar la inscripción en el Registro, o\nIII. Negar la inscripción cuando:\na) Se contravenga lo establecido en esta Ley, en el Reglamento, en las normas oficiales mexicanas, en el acuerdo general de implementación de la REP correspondiente, en el convenio de concertación suscrito o en otras disposiciones ambientales aplicables;\nb) La Huella Ambiental que forme parte de la solicitud se incremente, permanezca o no se reduzca significativamente en los plazos que señale el acuerdo general de implementación de la REP, el convenio de concertación suscrito;\nc) Exista falsedad en la información proporcionada por la persona productora o importadora o, en su caso, por el Organismo Coordinador, o\nd) El diseño del Producto carezca de medidas de compensación y no permita la circularidad, salvo causa justificada por inviabilidad ambiental, técnica o económica.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Primero De la Gestión Circular y su registro","seccion_nombre":null,"id":"227fffb2-2d47-4003-a3d7-834c7a089384","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":13},{"identificador":"Artículo 14","tipo_articulo":"ordinario","contenido":"La Gestión Circular que no sea autorizada o denegada por la Secretaría en un plazo de sesenta días hábiles, contados a partir del día en el que fue cargado para su inscripción en la Plataforma Nacional, adquiere el carácter de inscrito; en este caso, no es necesaria la notificación por parte de la Secretaría.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Primero De la Gestión Circular y su registro","seccion_nombre":null,"id":"929481ed-de1b-4d11-89d9-e838d9919822","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":14},{"identificador":"Artículo 15","tipo_articulo":"ordinario","contenido":"La solicitud de inscripción de la Gestión Circular debe contener la información, datos y documentos siguientes:\nI. Un Análisis del Ciclo de Vida por categoría de Producto. Cuando resulte ambiental, técnica y económicamente inviable, la solicitud podrá contener un estudio del Ciclo de Vida conforme a lo previsto en el acuerdo general de implementación de la REP y en los convenios de concertación previstos en la presente Ley, bajo las modalidades simplificadas que en estos se establezcan;\nII. Mecanismos directos o indirectos de circularidad que le apliquen y las metas que les correspondan;\nIII. Convenio de concertación, cuando se hubiese suscrito, y\nIV. Las demás que establezca el acuerdo general de implementación de la REP.\nLa Gestión Circular debe tener como fundamento las disposiciones aplicables de esta Ley, la LGPGIR, el Reglamento, el acuerdo general de implementación de la REP, el Convenio de Concertación correspondiente y demás normativa aplicable. Deben tomarse en cuenta los instrumentos ambientales autorizados y vigentes que sean compatibles y congruentes con esta Ley.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Primero De la Gestión Circular y su registro","seccion_nombre":null,"id":"2f0ef387-50c0-4df3-96a9-dfed0ab326f2","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":15},{"identificador":"Artículo 16","tipo_articulo":"ordinario","contenido":"La inscripción de la Gestión Circular y el cumplimiento a las metas de gradualidad y a las demás obligaciones que de dicha inscripción emanan, están sujetas a reportes establecidos en el acuerdo general de implementación de la REP y los convenios de concertación inscritos; la revisión puede ratificar, modificar o cancelar la inscripción en el Registro y sus condiciones.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Primero De la Gestión Circular y su registro","seccion_nombre":null,"id":"66fe5419-2641-4530-ab6a-c76d882d43bd","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":16},{"identificador":"Artículo 17","tipo_articulo":"ordinario","contenido":"Son instrumentos de política pública en materia de Economía Circular:\nI. El Programa Nacional;\nII. Los programas locales y municipales de Economía Circular;\nIII. La inscripción de la Gestión Circular;\nIV. Los programas de vigilancia e inspección del cumplimiento de la normativa;\nV. La auditoría ambiental voluntaria;\nVI. El Distintivo Nacional de Economía Circular;\nVII. Los instrumentos económicos, y\nVIII. Los demás que establezca la normativa en la materia.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":null,"id":"49589648-5014-4fbb-a8dd-89eb064d9826","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":17},{"identificador":"Artículo 18","tipo_articulo":"ordinario","contenido":"El Programa Nacional es un instrumento de planeación, en los términos de la Ley de Planeación, que integra, coordina e impulsa políticas públicas, subprogramas, proyectos y actividades, bajo los criterios y principios de Economía Circular previstos en la presente Ley, con el fin de alcanzar objetivos de protección ambiental, la implementación de mecanismos que sean ambiental, técnica y económicamente viables para la promoción del desarrollo de la Economía Circular.\n\nLos principios establecidos en el programa deben favorecer que los procesos productivos, sus productos o materiales generen una menor Huella Ambiental, contribuyan a reducir emisiones contaminantes, ahorren recursos naturales, minimicen residuos y en alineación con estándares nacionales e internacionales que eviten crear barreras técnicas al comercio sin justificación.\nEl Programa Nacional debe alinearse con el Plan Nacional de Desarrollo y a los programas sectoriales, en términos de la Ley de Planeación.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Primera Del Programa Nacional","id":"5eb4747a-5822-4d38-934d-a4dbfbe4f9a4","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":18},{"identificador":"Artículo 19","tipo_articulo":"ordinario","contenido":"La Secretaría debe elaborar el Programa Nacional con apoyo de las secretarías del ramo competentes, y con la participación de los sectores productivos.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Primera Del Programa Nacional","id":"33a76725-66d3-493d-96c9-1292d539c761","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":19},{"identificador":"Artículo 20","tipo_articulo":"ordinario","contenido":"El Programa Nacional debe establecer objetivos, ejes, metas generales, líneas estratégicas, metodologías, indicadores de Economía Circular y evaluaciones; que resulten ambiental, técnica y económicamente viables, así como los siguientes ejes de actuación:\nI. Establecer mecanismos que promuevan la coordinación entre la Federación, las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México, para transitar hacia una Economía Circular, con visión de corto, mediano y largo plazo, en el ámbito de sus respectivas competencias;\nII. Impulsar la vinculación entre los diferentes participantes de las cadenas de valor, bajo los principios de Economía Circular dispuestos en la presente Ley;\nIII. Facilitar mecanismos de cooperación con gobiernos extranjeros, empresas, organizaciones internacionales y agencias intergubernamentales, que fomenten e implementen la Economía Circular, conforme a los objetivos legítimos previstos en el mismo programa;\nIV. Promover que los procesos de generación del Producto e importación se apeguen a los principios, criterios y enfoques de la Gestión Circular y Economía Circular establecidos en la presente Ley;\nV. Diseñar y promover, con la coordinación y participación que corresponda a la Secretaría de Educación Pública y demás autoridades educativas, acciones orientadas a la difusión del conocimiento en temas de Economía Circular, así como su incorporación en programas educativos, que generen conciencia en la población e incidan en la transición hacia patrones de consumo y Producción cada vez más sostenibles;\nVI. Prever esquemas de coordinación para la generación institucional de indicadores de Economía Circular;\nVII. Establecer las medidas adecuadas para el desarrollo de mercados de materias primas secundarias y de residuos;\nVIII. Establecer acciones de regulación, monitoreo y vigilancia para el cumplimiento de la Responsabilidad Extendida del Productor;\nIX. Planear el desarrollo de indicadores de Economía Circular que permita evaluar el impacto de la Economía Circular en el país;\nX. Fortalecer la vinculación entre sectores productivos para optimizar las cadenas de valor y minimizar pérdidas de materiales vírgenes o materias primas secundarias;\nXI. Fomentar la participación activa de las personas, la sociedad civil organizada y el sector privado en las estrategias y acciones de Economía Circular;\nXII. Identificar los sectores productivos y categorías de productos sobre los cuales podrán emitirse acuerdos generales de implementación de la REP, a partir de las necesidades ambientales y la viabilidad técnica y económica;\nXIII. Promover sistemas que reduzcan los impactos negativos al ambiente, mediante mecanismos directos e indirectos de circularidad y que fomenten la aplicación de los principios de Economía Circular durante la Producción;\nXIV. Fomentar el desarrollo y uso de tecnologías sustentables, así como el uso de mecanismos directos e indirectos de circularidad que favorezcan la transición hacia una Economía Circular, y\nXV. Los demás que se establezcan en el Reglamento.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Primera Del Programa Nacional","id":"b58feab4-8042-47f5-a407-54dcb14e9524","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":20},{"identificador":"Artículo 21","tipo_articulo":"ordinario","contenido":"En los ejes de actuación del Programa Nacional, referidos en el artículo anterior, se deben prever, conforme a la normativa aplicable, las siguientes acciones:\nI. Impulsar la Producción responsable y eficiente mediante modelos de desarrollo económico sostenible que promuevan la protección ambiental, a través de acciones que faciliten esquemas de Encadenamiento Sustentable que maximicen el uso y Aprovechamiento Circular del Producto, de materiales y recursos dentro de la Cadena de Valor, que contribuyan a reducir la extracción de materiales vírgenes y uso de sustancias tóxicas;\nII. Fomentar el Diseño Circular desde la Producción, con criterios que optimicen el uso de Material Virgen, la incorporación de materias primas secundarias y materiales reciclados en la Producción, así como la minimización del uso de sustancias tóxicas o contaminantes, a fin de obtener productos de fácil Aprovechamiento Circular o, en su caso, de su disposición final;\nIII. Fomentar modelos de servicio de uso compartido que permitan satisfacer necesidades sin que sea indispensable la adquisición o posesión de los productos;\nIV. Diseñar y establecer programas de cultura de Consumo Responsable, mediante campañas informativas a la ciudadanía sobre las implicaciones ambientales en cada etapa del Ciclo de Vida de los productos, y las alternativas para el aprovechamiento de los materiales al final de su vida útil, así como la separación en fuente de los residuos sólidos urbanos y de manejo especial, su adecuada separación y aprovechamiento;\nV. Impulsar mercados circulares de materias primas secundarias y de residuos que faciliten su incorporación en la Cadena de Valor y que, en consecuencia, reduzcan la extracción de Material Virgen;\nVI. Prevenir y minimizar la generación de residuos, con el establecimiento de acciones preventivas y mecanismos directos e indirectos de circularidad para la prevención de la generación y minimización de residuos, con base en el principio de jerarquización establecido en esta Ley;\nVII. Establecer como criterio el rediseño o modificación intencional de productos que no fueron consumidos, conforme a la presente Ley, con la finalidad de reducir el impacto ambiental;\nVIII. Fomentar la cultura de la reutilización de productos y materiales, para incrementar la vida útil de estos, y mantenerlos dentro de la economía el mayor tiempo posible;\nIX. Impulsar la Gestión Circular, incluido el Diseño Circular, y establecer esquemas que contemplen la reparabilidad del Producto, así como facilitar la accesibilidad de las personas consumidoras a esta acción, para fomentar la reparación de productos, antes que el desecho y reemplazo del Producto;\nX. Impulsar la implementación de modelos de gestión con perspectiva de Reciclaje Inclusivo;\nXI. Fomentar la reutilización, reparación o reacondicionamiento de productos que pueden volver a servir para lo que fueron creados;\nXII. Establecer la gradualidad y definir metas para:\na) El uso sostenible de los recursos naturales y el aprovechamiento sostenible del agua;\nb) La clasificación adecuada de los residuos, que incluya lineamientos armonizados para todas las entidades federativas;\nc) La reducción del desperdicio de alimentos;\nd) El reciclaje de materiales y residuos de interés nacional, así como aquellos comprometidos en convenios internacionales;\ne) La incorporación de materiales reciclados en productos y la sustitución en estos de sustancias tóxicas por otras que no lo sean, y\nf) La reducción de la disposición final en rellenos sanitarios;\nXIII. Las demás actividades y acciones que permitan incentivar la transición a la Economía Circular.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Primera Del Programa Nacional","id":"8a21c26b-8725-47f8-813c-66753f3ada1e","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":21},{"identificador":"Artículo 22","tipo_articulo":"ordinario","contenido":"En los ejes de actuación del Programa Nacional, referidos en el artículo anterior de esta Ley, se deben prever las siguientes acciones transversales para la Administración Pública Federal:\n\nI. Acción climática: Las acciones que contribuyan a disminuir emisiones de gases de efecto invernadero y carbono negro, así como aquellas encaminadas a fortalecer la adaptación y resiliencia al cambio climático, con atención prioritaria a grupos vulnerables, en congruencia y de manera complementaria con lo establecido en la Ley General de Cambio Climático y demás normativa aplicable;\nII. Creación de empleos: Acciones que generen puestos de trabajo relacionados con los Criterios y Principios de Economía Circular para la protección y restauración del medio ambiente, que incrementen la inclusión social y el crecimiento económico sostenible;\nIII. Innovación tecnológica: Desarrollo y adopción de nuevas tecnologías que permitan optimizar los procesos de generación de productos circulares, y dé prioridad a la eficiencia en el uso de recursos;\nIV. Consumo Responsable: Promover la toma de decisiones informada con respecto al consumo del Producto, para que los procesos productivos sean más eficientes y sustentables;\nV. Educación y cultura de la circularidad: Fortalecimiento del conocimiento de la población sobre el tema de Economía Circular, a fin de facilitar su aplicación y la adopción de estilos de vida sustentables;\nVI. Promover las buenas prácticas regulatorias;\nVII. Reciclaje Inclusivo: reconocer y visibilizar la aportación social, económica y ambiental de la actividad de las personas recicladoras de base o pepenadoras, así como el desarrollo e implementación de modelos que incluyan a estas personas en la Economía Circular;\nVIII. Implementar las medidas de control, inspección, vigilancia y verificación que, en su caso, correspondan, y\nIX. Las demás que se establezcan en el Reglamento.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Primera Del Programa Nacional","id":"6f22c6cf-5e35-446b-954d-62780e228e70","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":22},{"identificador":"Artículo 23","tipo_articulo":"ordinario","contenido":"La Secretaría autorizará el uso del Distintivo Nacional de Economía Circular para identificar los productos que cumplen con los principios y criterios de Economía Circular. El distintivo brinda información veraz, verificable y accesible al consumidor respecto del cumplimiento a lo dispuesto por esta Ley.\nLos requisitos y formalidades para el uso del Distintivo Nacional de Economía Circular se establecen en el Reglamento de la presente Ley.\nEl uso del Distintivo queda sujeto a la autorización que emita la Secretaría con base en el proceso de auditoría ambiental voluntaria de acuerdo con el cumplimiento de los acuerdos generales de implementación de la REP y los convenios de concertación.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Segunda Del Distintivo Nacional de Economía Circular","id":"bb79e6e6-48b2-4cec-b259-cd119cf4defe","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":23},{"identificador":"Artículo 24","tipo_articulo":"ordinario","contenido":"El Distintivo Nacional de Economía Circular tiene una vigencia de tres años, con posibilidad de renovarse, en cumplimiento con los fines de esta Ley y conforme a las disposiciones del Reglamento.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Segunda Del Distintivo Nacional de Economía Circular","id":"4ef0ea2a-a291-4da8-b878-4c4901a0eaf5","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":24},{"identificador":"Artículo 25","tipo_articulo":"ordinario","contenido":"El Producto que cuente con la autorización para el uso del Distintivo Nacional de Economía Circular tendrá preferencia para su adquisición, en términos de las disposiciones jurídicas aplicables en materia de contrataciones públicas.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Segunda Del Distintivo Nacional de Economía Circular","id":"a2572f8c-7577-4a1f-aef5-49f2839a833c","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":25},{"identificador":"Artículo 26","tipo_articulo":"ordinario","contenido":"Al Ejecutivo Federal le corresponde la expedición de instrumentos económicos para fomentar la Economía Circular, alineados con el Programa Nacional y al Reglamento de esta Ley. Los instrumentos que contengan estímulos fiscales deben sujetarse a las disposiciones fiscales aplicables.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Tercera Del Instrumento Económico","id":"6f2fb502-561f-4f6f-baf6-a7e921577777","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":26},{"identificador":"Artículo 27","tipo_articulo":"ordinario","contenido":"Las entidades federativas, conforme a sus atribuciones, diseñarán y promoverán instrumentos económicos que fomenten la Economía Circular dentro de sus respectivas jurisdicciones competenciales, así como proponer a la autoridad competente de la Administración Pública Federal los instrumentos económicos que se puedan aplicar, incluidos a los modelos de complementariedad.","titulo_nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","capitulo_nombre":"Capítulo Segundo De los instrumentos de política pública","seccion_nombre":"Sección Tercera Del Instrumento Económico","id":"3b46bc6f-e531-4791-8599-3bdda430d635","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":27},{"identificador":"Artículo 28","tipo_articulo":"ordinario","contenido":"A la Secretaría, en la calidad de presidencia del Sistema, le corresponde implementar, coordinar y operar la Plataforma Nacional, para el registro y difusión de información en la materia de Economía Circular, con la participación de las dependencias de la Administración Pública Federal en el ámbito de sus respectivas competencias.","titulo_nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","capitulo_nombre":"Capítulo Primero De la Plataforma Nacional","seccion_nombre":null,"id":"3da04c0e-3048-48b8-bd52-a531d587f4f2","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":28},{"identificador":"Artículo 29","tipo_articulo":"ordinario","contenido":"Para el funcionamiento y operación de la Plataforma Nacional, los sujetos obligados deben, permanentemente integrar y actualizar el contenido de esta, así como realizar las acciones necesarias para que la información del Sistema tenga la mayor difusión posible entre la población.\nEl Instituto Nacional de Estadística y Geografía participará en la implementación, coordinación y operación de la Plataforma Nacional para registrar y difundir información sobre Economía Circular, con apego a lo establecido en la Ley del Sistema Nacional de Información Estadística y Geográfica.\nLas dependencias y entidades de la Administración Pública Federal deben proporcionar la información que les soliciten las autoridades que coordinan la implementación y operación de la Plataforma Nacional, en los términos de las disposiciones jurídicas aplicables y, en su caso, los convenios que se celebren para tales efectos.","titulo_nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","capitulo_nombre":"Capítulo Primero De la Plataforma Nacional","seccion_nombre":null,"id":"5e6f939c-2406-4c6e-a68d-f661206aae92","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":29},{"identificador":"Artículo 30","tipo_articulo":"ordinario","contenido":"La Plataforma Nacional debe contener lo siguiente:\nI. El Programa Nacional;\nII. Información básica de divulgación sobre la Economía Circular;\nIII. Información sobre los modelos de servicio, así como de otros modelos de negocio circulares más representativos;\nIV. Información que permita la adopción de prácticas de Economía Circular en la población y los sectores productivos;\nV. El directorio de empresas que cuentan con el Distintivo Nacional de Economía Circular y, en su caso, otros distintivos de circularidad otorgados por entidades federativa en términos de las disposiciones aplicables;\nVI. La trazabilidad de productos establecidos en los acuerdos generales de implementación de la REP, y\nVII. La demás información que se requiera para alimentar a la Plataforma Nacional.","titulo_nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","capitulo_nombre":"Capítulo Primero De la Plataforma Nacional","seccion_nombre":null,"id":"b8ac42d3-48d8-46bc-888f-0e38985bf7a5","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":30},{"identificador":"Artículo 31","tipo_articulo":"ordinario","contenido":"El Gobierno Federal, los gobiernos de las entidades federativas, de los municipios y las demarcaciones territoriales de la Ciudad de México, en sus respectivos ámbitos de competencia, deben promover la participación y el involucramiento de los distintos sectores en la generación de materiales que contribuyan a impulsar la corresponsabilidad social y la transición hacia modelos de Economía Circular, así como propiciar la generación de campañas de comunicación masiva, para lo cual pueden utilizar diversos medios, para el fortalecimiento de la conciencia ambiental y la adopción de hábitos de Consumo Responsable, así como para la divulgación de una perspectiva de Reciclaje Inclusivo.\nLos tres órdenes de gobierno deben propiciar la participación e involucramiento de los diferentes sectores de la sociedad para el cumplimiento del presente artículo.","titulo_nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","capitulo_nombre":"Capítulo Segundo De la educación, la cultura y la investigación en materia de Economía Circular","seccion_nombre":null,"id":"4b7a5b71-2081-4897-9e5c-a67b6dc3da97","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":31},{"identificador":"Artículo 32","tipo_articulo":"ordinario","contenido":"La Secretaría, así como las secretarías del ramo en materia de economía, de educación pública, de salud, y de ciencia, humanidades, tecnología e innovación deben establecer la coordinación que sea necesaria para el cumplimiento de las atribuciones que esta Ley le confiere a la Administración Pública Federal.\nA la Secretaría de Educación Pública le corresponde promover que en los planes de educación media superior y superior se desarrollen programas de estudio para la formación de especialistas en materia medioambiental, particularmente en medio ambiente y sustentabilidad, gestión ambiental, Economía Circular y demás campos de la ciencia que son afines para lograr los objetivos de la presente Ley.","titulo_nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","capitulo_nombre":"Capítulo Segundo De la educación, la cultura y la investigación en materia de Economía Circular","seccion_nombre":null,"id":"1c90e67b-da7f-48d2-94ef-15fe23cfac3d","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":32},{"identificador":"Artículo 33","tipo_articulo":"ordinario","contenido":"La Secretaría en forma coordinada y con la participación de la Secretaría de Educación Pública debe promover que las instituciones de educación media superior, superior, y los organismos dedicados a la investigación científica y tecnológica, desarrollen planes y programas para la formación de especialistas en la materia de Economía Circular en el territorio nacional, así como para la investigación y generación de tecnologías que faciliten la transición hacia la Economía Circular.\n\nAsimismo, la Secretaría de Educación Pública y las autoridades educativas de las entidades federativas, en el ámbito de sus respectivas competencias, promoverán de manera progresiva programas escolares de Economía Circular en los planteles públicos de educación básica, media superior y superior.","titulo_nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","capitulo_nombre":"Capítulo Segundo De la educación, la cultura y la investigación en materia de Economía Circular","seccion_nombre":null,"id":"6ba5c752-eb6d-41e1-9ae4-8060cc0cb004","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":33},{"identificador":"Artículo 34","tipo_articulo":"ordinario","contenido":"La Secretaría de Ciencia, Humanidades, Tecnología e Innovación debe integrar en el ámbito de sus atribuciones, la perspectiva de Economía Circular en la innovación, el desarrollo tecnológico y el fortalecimiento de la planta productiva nacional, conforme a sus atribuciones y los ordenamientos aplicables.","titulo_nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","capitulo_nombre":"Capítulo Segundo De la educación, la cultura y la investigación en materia de Economía Circular","seccion_nombre":null,"id":"cc566e5d-85d3-4c1d-a2ec-352348399bbe","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":34},{"identificador":"Artículo 35","tipo_articulo":"ordinario","contenido":"La Secretaría promoverá por conducto de la Procuraduría Federal de Protección al Ambiente la realización de auditorías ambientales voluntarias, conforme a las disposiciones de la presente Ley, la Ley General del Equilibrio Ecológico y la Protección al Ambiente, y demás normativa aplicable.\nLa auditoría en materia de Economía Circular, para efectos de esta Ley, es el proceso sistemático de verificación, y voluntario de carácter preventivo y, en su caso, correctivo, que permite evaluar el grado de cumplimiento de los principios, disposiciones, criterios y objetivos en materia de Economía Circular, así como de la normativa aplicable. La finalidad de la evaluación es identificar oportunidades de mejora en los procesos, optimizar el uso de recursos y minimizar los impactos ambientales; así como favorecer la adopción de buenas prácticas y el fortalecimiento de la competitividad del sector productivo.\nEl Reglamento debe prever los procedimientos, requisitos y demás disposiciones relativas a la auditoría en materia de Economía Circular, a fin de establecer criterios técnicos, metodologías de evaluación, acreditación de auditores y los mecanismos de supervisión que aseguren su implementación efectiva, con el objeto de definir las medidas preventivas y correctivas necesarias.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Primero De la auditoría ambiental voluntaria en materia de economía circular","seccion_nombre":null,"id":"59cd26e2-7092-4adb-88c0-d17531fa1c01","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":35},{"identificador":"Artículo 36","tipo_articulo":"ordinario","contenido":"Los sectores productivos tienen la obligación de generar o desarrollar productos con Diseño Circular, cuando ello resulte ambiental, técnica y económicamente viable, así como implementar las políticas, bases y principios de Economía Circular bajo un esquema de Responsabilidad Extendida del Productor en su Actividad Económica conforme a los acuerdos generales de implementación de la REP y, en su caso, los convenios de concertación.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Segundo De la responsabilidad empresarial y Responsabilidad Extendida del Productor o REP","seccion_nombre":null,"id":"ecf0da64-8022-452d-93fb-516d37844fea","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":36},{"identificador":"Artículo 37","tipo_articulo":"ordinario","contenido":"Los sectores productivos e importadores están obligados a organizar, fomentar y, en su caso, financiar los esquemas de Economía Circular de los productos que generan o importan, conforme a esta Ley, los acuerdos de implementación de la REP y, en su caso, los convenios de concertación; o de los aprovechamientos de los residuos y mediante la recuperación del valor de estos, conforme a las disposiciones de la LGPGIR, con la finalidad de incorporar materias primas secundarias a las cadenas de valor.\nLas obligaciones de la persona productora son complementarias y no excluyen las obligaciones que surgen de la responsabilidad compartida prevista en la LGPGIR, así como aquellas que corresponden al consumidor y a la autoridad competente.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Segundo De la responsabilidad empresarial y Responsabilidad Extendida del Productor o REP","seccion_nombre":null,"id":"e416f1aa-101d-4c76-a848-b5044d42adc6","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":37},{"identificador":"Artículo 38","tipo_articulo":"ordinario","contenido":"El Organismo Coordinador tiene la obligación de promover estrategias para implementar los mecanismos directos e indirectos de circularidad en procesos productivos circulares, así como las demás acciones que maximicen la vida útil del Producto, la recuperación del valor de los residuos, y que den impulso a la Economía Circular.\nEl Organismo Coordinador es corresponsable con el sector de producción al que representa, en la elaboración de la Gestión Circular que la persona productora o importadora debe inscribir en la Plataforma Nacional, conforme a los términos de su representación, así como en el cumplimiento de las acciones que conllevan dicho diseño, por lo que también le es aplicable la Responsabilidad Extendida del Productor.\nLos requisitos y los procedimientos para la inscripción de la Gestión Circular en el Registro, así como las funciones y mecanismos de supervisión que le corresponde efectuar al Organismo Coordinador se deben pormenorizar en el Reglamento, con el fin de precisar su acreditación ante las autoridades, el alcance de sus facultades y la forma de coordinarse con personas productoras, importadoras, autoridades y otros actores involucrados en la Economía Circular.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Segundo De la responsabilidad empresarial y Responsabilidad Extendida del Productor o REP","seccion_nombre":null,"id":"2d7b47a4-1ebc-4556-8d08-e29f8ce8cf2b","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":38},{"identificador":"Artículo 39","tipo_articulo":"ordinario","contenido":"La persona productora, importadora o, en su caso, el Organismo Coordinador tiene la obligación de efectuar la inscripción en el Registro de la Gestión Circular en la Plataforma Nacional.\nLa Gestión Circular debe contener las etapas y las acciones que correspondan al Ciclo de Vida, incluido el Diseño Circular, conforme al artículo 15 de esta Ley.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Segundo De la responsabilidad empresarial y Responsabilidad Extendida del Productor o REP","seccion_nombre":null,"id":"7b953785-579b-416e-8ed0-5d213fc7f51e","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":39},{"identificador":"Artículo 40","tipo_articulo":"ordinario","contenido":"El cumplimiento de las obligaciones se clasifica como de:\nI. Cumplimiento directo, cuando la persona productora o importadora aplica mecanismos directos de circularidad sin mediación de terceras personas, y\nII. Cumplimiento indirecto, cuando la persona productora o importadora aplica mecanismos indirectos de circularidad con intervención de terceras personas, a través del acuerdo celebrado para el Encadenamiento Sustentable o mediante compensación ambiental.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Segundo De la responsabilidad empresarial y Responsabilidad Extendida del Productor o REP","seccion_nombre":null,"id":"191d74e3-8b31-41fa-9342-41afd4667860","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":40},{"identificador":"Artículo 41","tipo_articulo":"ordinario","contenido":"La Responsabilidad Extendida del Productor también puede cumplirse mediante las medidas de compensación ambiental cuando, por causas debidamente justificadas, la persona productora, importadora o, en su caso, el Organismo Coordinador no pueda cumplir con las obligaciones previstas en esta Ley bajo el esquema de Responsabilidad Extendida del Productor; en estos casos debe cumplir con las medidas de compensación ambiental previstas en la Gestión Circular registrada.\nLa Secretaría, mediante acuerdos generales de implementación de la REP, establecerá los casos, criterios técnicos, procedimientos y condiciones para determinar dichas medidas.\nEn los casos en los que se apliquen medidas de compensación ambiental se debe mitigar o revertir de manera proporcional a la Huella Ambiental. Estas pueden consistir en:\nI. Restauración ecológica;\nII. Conservación y preservación de áreas naturales protegidas;\nIII. Reparación del daño ambiental, conforme a la legislación aplicable;\nIV. Reforestación;\nV. Reducción de emisiones contaminantes, y\nVI. Adquisición o generación de instrumentos financieros certificados, como bonos verdes, créditos de carbono u otros mecanismos equivalentes, siempre y cuando dichos instrumentos estén regulados o validados por la autoridad competente en materia financiera o ambiental.\nLa autoridad competente que conforme a sus atribuciones emita una resolución ambiental debe tomar en cuenta las medidas equivalentes de compensación que lleve a cabo la persona productora en cumplimiento a una resolución impuesta con base a otra normativa ambiental, cuando esté relacionada con el mismo hecho o la misma conducta, siempre que tenga congruencia con el acuerdo general de implementación de la REP y cumpla con indicadores de Economía Circular.\nEn el Reglamento se establecen los procedimientos para incluir las medidas de compensación ambiental en la Gestión Circular.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Segundo De la responsabilidad empresarial y Responsabilidad Extendida del Productor o REP","seccion_nombre":null,"id":"5f9060a8-5928-4305-b316-700670a416bb","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":41},{"identificador":"Artículo 42","tipo_articulo":"ordinario","contenido":"La población participa en la Economía Circular mediante los hábitos de Consumo Responsable siguientes:\nI. Realizar un Consumo Responsable, informado y sostenible de productos; con preferencia a aquellos que son duraderos y son generados mediante un uso eficiente del agua y de energía, y evitar aquellos productos de un solo uso;\nII. Adoptar medidas de Aprovechamiento Circular que optimicen la vida útil del Producto;\nIII. Optar por modelos de servicio cuando se oferte que, sin adquirir la propiedad de los productos, se satisfagan las necesidades de consumo;\nIV. Reducir la generación de residuos y el desperdicio de agua, de energía, de productos y de alimentos;\nV. Separar los residuos en sus viviendas, de acuerdo con el sistema de clasificación que se establezca para tal fin, y\nVI. Aprovechar al máximo los materiales y los residuos, mediante procesos de compostaje, mecanismos de circularidad y prácticas de Reciclaje Inclusivo, entre otros.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Tercero De la responsabilidad social y la participación de las personas consumidoras","seccion_nombre":null,"id":"de5b488d-9d39-4697-b917-a22e08c994bf","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":42},{"identificador":"Artículo 43","tipo_articulo":"ordinario","contenido":"Las personas físicas o morales tienen prohibido:\nI. Generar o utilizar información falsa respecto de las características medioambientales de uno o más productos;\nII. Generar o utilizar información sobre el desarrollo de su Proceso o de sus procesos apegados a criterios o principios de Economía Circular, cuando dicha información sea falsa;\nIII. Realizar u omitir acciones que impidan maximizar la vida útil del Producto y su Aprovechamiento Circular;\nIV. Usar en productos el Distintivo Nacional de Economía Circular, sin contar con la autorización correspondiente;\nV. Usar el Distintivo Nacional de Economía Circular sin autorización de la Secretaría, o una etiqueta o distintivo que pueda confundir a las personas consumidoras, y\nVI. Las demás que se establecen en el Reglamento.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Tercero De la responsabilidad social y la participación de las personas consumidoras","seccion_nombre":null,"id":"c2030223-a403-469e-97f5-3908c138b1d0","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":43},{"identificador":"Artículo 44","tipo_articulo":"ordinario","contenido":"La persona productora, importadora o el Organismo Coordinador responsable de fuentes de generación o manejo del Producto, o materias reguladas por esta Ley o en el Reglamento debe proporcionar a la Secretaría los informes, o documentos conforme a las obligaciones previstas en la Gestión Circular inscrita en el Registro, dentro del plazo que establecen las disposiciones jurídicas aplicables.\nEn caso de no cumplir con esta obligación se les aplicarán las sanciones administrativas previstas en la Ley General del Equilibrio Ecológico y la Protección al Ambiente.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Cuarto De las responsabilidades y sanciones","seccion_nombre":null,"id":"d252d96c-13b9-5ffe-a614-70896fbea536","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":44},{"identificador":"Artículo 45","tipo_articulo":"ordinario","contenido":"Las infracciones cometidas a esta Ley y a su Reglamento, serán sancionadas por la Secretaría, conforme lo establecen los artículos 171 y 173 de la Ley General del Equilibrio Ecológico y la Protección al Ambiente.\nLo anterior, sin perjuicio de la responsabilidad por daños al ambiente, así como de las penas que correspondan cuando los actos u omisiones constituyan delitos.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Cuarto De las responsabilidades y sanciones","seccion_nombre":null,"id":"226c326a-5e42-4065-95a0-bc4508d789ee","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":45},{"identificador":"Artículo 46","tipo_articulo":"ordinario","contenido":"La Secretaría tiene la facultad potestativa de convenir con la persona infractora mecanismos alternativos de solución de controversias.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Cuarto De las responsabilidades y sanciones","seccion_nombre":null,"id":"304f06b6-bf80-4ff4-8141-f0b26d0b029e","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":46},{"identificador":"Artículo 47","tipo_articulo":"ordinario","contenido":"La Secretaría, mediante acuerdos generales de implementación de la REP que deben publicarse en el Diario Oficial de la Federación, puede establecer la gradualidad diferenciada para el cumplimiento de las disposiciones de circularidad, mediante metas que fije con base en las capacidades económicas, financieras, y tecnológicas de cada persona productora, Producción o importación, en particular de las micro, pequeñas y medianas empresas, así como la aplicación de mecanismos directos e indirectos de circularidad, la suscripción de convenios y la ejecución de las demás medidas que establece esta Ley.\nLas micro, pequeñas y medianas empresas son aquellas que se prevén en sus términos en la Ley para el Desarrollo de la Competitividad de la Micro, Pequeña y Mediana Empresa.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Quinto De la gradualidad","seccion_nombre":null,"id":"eb54016a-83de-4963-9f51-d82c9085935e","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":47},{"identificador":"Artículo 48","tipo_articulo":"ordinario","contenido":"La Secretaría debe establecer esquemas y metas de gradualidad de cumplimiento de las obligaciones previstas en los artículos 13, 15, 23 y 47 de esta Ley, y para tal fin puede suscribir convenios de concertación con la persona productora, importadora o con el Organismo Coordinador. Para la celebración de estos convenios se deben evaluar los efectos que genere la gradualidad en las metas de cumplimiento y las propuestas de la persona productora, en particular de las micro, pequeñas y medianas empresas, importadoras o del Organismo Coordinador. Estos convenios son de interés general y se publicarán en el Diario Oficial de la Federación.","titulo_nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","capitulo_nombre":"Capítulo Quinto De la gradualidad","seccion_nombre":null,"id":"b702e834-7c0d-44c9-b10a-29fc5a1568dd","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":48},{"identificador":"Artículo 49","tipo_articulo":"ordinario","contenido":"En lo no previsto en esta Ley se aplicarán supletoriamente la Ley General del Equilibrio Ecológico y la Protección al Ambiente, la Ley General para la Prevención y Gestión Integral de Residuos, la Ley Federal de Procedimiento Administrativo y la normativa aplicable.","titulo_nombre":"Título Sexto De la aplicación supletoria","capitulo_nombre":null,"seccion_nombre":null,"id":"3038ee1d-0b43-4afe-964d-e19dd42abec2","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":49},{"identificador":"Transitorio Primero","tipo_articulo":"transitorio","contenido":"El presente Decreto entrará en vigor el día siguiente al de su publicación en el Diario Oficial de la Federación.","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"b3f88725-e252-42e6-9a9f-dd5531e3c4db","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":50},{"identificador":"Transitorio Segundo","tipo_articulo":"transitorio","contenido":"El Ejecutivo Federal, dentro de los ciento ochenta días naturales posteriores a la entrada en vigor del presente Decreto, deberá expedir el o los reglamentos de la Ley General de Economía Circular.\nLas autoridades competentes de la Administración Pública Federal iniciarán el procedimiento administrativo para modificar y adecuar las normas oficiales mexicanas existentes, así como el procedimiento administrativo para la creación y expedición de las normas oficiales mexicanas que se requieran, conforme a las disposiciones jurídicas aplicables.\nPara la implementación de esta disposición transitoria debe seguirse lo establecido en la fracción III del artículo 6 de esta Ley.","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"5c4ca336-bbb8-476f-922e-61478937aff9","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":51},{"identificador":"Transitorio Tercero","tipo_articulo":"transitorio","contenido":"El Programa Nacional de Economía Circular se publicará en el Diario Oficial de la Federación en un plazo no mayor a ciento ochenta días naturales, contados a partir de la publicación del Reglamento de la presente Ley. En la identificación de sectores productivos y categorías de productos del Programa 2026-2030 deben incluirse aquellos correspondientes al plástico que, en términos de los procedimientos de la Ley de Planeación, determine la Secretaría.","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"49e5464c-2449-4ee2-b921-3e921b93b064","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":52},{"identificador":"Transitorio Cuarto","tipo_articulo":"transitorio","contenido":"Dentro del plazo de ciento ochenta días naturales contados a partir de la entrada en vigor de la presente Ley, las legislaturas de las entidades federativas adecuarán y armonizarán su legislación con las disposiciones de la Ley General de Economía Circular que se expide con el presente Decreto.","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"0486ecaa-9211-4c17-baf4-afe734980d7b","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":53},{"identificador":"Transitorio Quinto","tipo_articulo":"transitorio","contenido":"Las legislaturas locales que no efectúen la armonización que se indica en el transitorio anterior deberán aplicar las disposiciones de esta Ley, en el ámbito local.","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"76261bbe-2b83-4901-8754-a75329430901","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":54},{"identificador":"Transitorio Sexto","tipo_articulo":"transitorio","contenido":"A partir de la entrada en vigor de la presente Ley y dentro del plazo de cinco años con prórroga por acuerdo casuístico, los rellenos sanitarios autorizados iniciarán un proceso progresivo de reconversión para cumplir con las metas de reducción de la disposición final para promover su integración en el Modelo de Economía Circular Nacional.","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"938dab1f-c72e-4087-9f2d-c2aadc9576da","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":55},{"identificador":"Transitorio Séptimo","tipo_articulo":"transitorio","contenido":"Las erogaciones que, en su caso, se generen con motivo de la entrada en vigor de la presente Ley se realizarán con cargo al presupuesto aprobado a la Secretaría de Medio Ambiente y Recursos Naturales, para el presente ejercicio fiscal y los subsecuentes en el Presupuesto de Egresos de la Federación, las modificaciones a la estructura orgánica deberán llevarse a cabo mediante movimientos compensados conforme a las disposiciones jurídicas aplicables, por lo que no incrementará su presupuesto regularizable de gasto de operación ni de servicios personales y no se autorizarán recursos adicionales para el ejercicio fiscal de que se trate.","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"2479fdd9-8d5f-43e7-bc0b-3b5b243b9729","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":56},{"identificador":"Firmas y promulgación","tipo_articulo":"complementario","contenido":"Ciudad de México, a 10 de diciembre de 2025.- Dip. Kenia López Rabadán, Presidenta.- Sen. Laura Itzel Castillo Juárez, Presidenta.- Dip. Magdalena del Socorro Núñez Monreal, Secretaria.- Sen. María Martina Kantún Can, Secretaria.- Rúbricas.\"\nEn cumplimiento de lo dispuesto por la fracción I del Artículo 89 de la Constitución Política de los Estados Unidos Mexicanos, y para su debida publicación y observancia, expido el presente Decreto en la Residencia del Poder Ejecutivo Federal, en la Ciudad de México, a 14 de enero de 2026.- Claudia Sheinbaum Pardo, Presidenta de los Estados Unidos Mexicanos.- Rúbrica.- Lcda. Rosa Icela Rodríguez Velázquez, Secretaria de Gobernación.- Rúbrica.","titulo_nombre":"Documentos complementarios","capitulo_nombre":null,"seccion_nombre":null,"id":"f82885ed-9924-5f57-a17e-5304a7dd0d95","ley_id":"552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c","orden":57}],"remove":[],"themes_before":[],"themes_after":[{"nivel":"titulo","nombre":"Título Primero Disposiciones Generales","orden":0},{"nivel":"capitulo","nombre":"Capítulo Primero Del objeto y ámbito de aplicación","orden":1},{"nivel":"capitulo","nombre":"Capítulo Segundo Criterios y principios de Economía Circular","orden":2},{"nivel":"titulo","nombre":"Título Segundo Sistema Nacional de Economía Circular y distribución de competencias","orden":3},{"nivel":"capitulo","nombre":"Capítulo Primero Del Sistema Nacional de Economía Circular","orden":4},{"nivel":"capitulo","nombre":"Capítulo Segundo De la distribución de competencias","orden":5},{"nivel":"titulo","nombre":"Título Tercero De las políticas públicas y mecanismos de circularidad","orden":6},{"nivel":"capitulo","nombre":"Capítulo Primero De la Gestión Circular y su registro","orden":7},{"nivel":"capitulo","nombre":"Capítulo Segundo De los instrumentos de política pública","orden":8},{"nivel":"seccion","nombre":"Sección Primera Del Programa Nacional","orden":9},{"nivel":"seccion","nombre":"Sección Segunda Del Distintivo Nacional de Economía Circular","orden":10},{"nivel":"seccion","nombre":"Sección Tercera Del Instrumento Económico","orden":11},{"nivel":"titulo","nombre":"Título Cuarto De la información, la educación, la cultura y la investigación","orden":12},{"nivel":"capitulo","nombre":"Capítulo Primero De la Plataforma Nacional","orden":13},{"nivel":"capitulo","nombre":"Capítulo Segundo De la educación, la cultura y la investigación en materia de Economía Circular","orden":14},{"nivel":"titulo","nombre":"Título Quinto De las obligaciones y las responsabilidades ambientales","orden":15},{"nivel":"capitulo","nombre":"Capítulo Primero De la auditoría ambiental voluntaria en materia de economía circular","orden":16},{"nivel":"capitulo","nombre":"Capítulo Segundo De la responsabilidad empresarial y Responsabilidad Extendida del Productor o REP","orden":17},{"nivel":"capitulo","nombre":"Capítulo Tercero De la responsabilidad social y la participación de las personas consumidoras","orden":18},{"nivel":"capitulo","nombre":"Capítulo Cuarto De las responsabilidades y sanciones","orden":19},{"nivel":"capitulo","nombre":"Capítulo Quinto De la gradualidad","orden":20},{"nivel":"titulo","nombre":"Título Sexto De la aplicación supletoria","orden":21}],"date_before":"12026-02-19","date_after":"2026-01-19"}$payload$::jsonb; lid uuid; n integer;
BEGIN
 lid := (p->>'ley_id')::uuid;
 LOCK TABLE public.articulos, public.temas, public.user_favorites, public.user_notes IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.leyes WHERE id=lid FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.leyes WHERE id=lid AND fecha_publicacion=(p->>'date_before')::date) THEN RAISE EXCEPTION 'Cambió la fecha o el instrumento'; END IF;
 SELECT count(*) INTO n FROM public.articulos WHERE ley_id=lid;
 IF n<>jsonb_array_length(p->'before') THEN RAISE EXCEPTION 'Cambió el conteo antes de aplicar'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'before') b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR md5(a.contenido) IS DISTINCT FROM b->>'contenido_md5' OR (to_jsonb(a)-'contenido'-'fts'-'created_at') IS DISTINCT FROM (b-'contenido_md5')) THEN RAISE EXCEPTION 'El respaldo ya no coincide con los artículos'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'themes_before') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'themes_before') b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE t.ley_id=lid AND (to_jsonb(t)-'created_at')=b)) THEN RAISE EXCEPTION 'Cambió el índice de temas'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_favorites f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) OR EXISTS(SELECT 1 FROM public.user_notes f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) THEN RAISE EXCEPTION 'Hay referencias nuevas a fragmentos que se unirán: revisar traslado'; END IF;
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden)
 SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'after')
 ON CONFLICT(id) DO UPDATE SET identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre,orden=excluded.orden;
 DELETE FROM public.articulos WHERE ley_id=lid AND id IN(SELECT jsonb_array_elements_text(p->'remove')::uuid);
 DELETE FROM public.temas WHERE ley_id=lid;
 insert into public.temas(ley_id,nivel,nombre,orden) select lid,t->>'nivel',t->>'nombre',(t->>'orden')::int from jsonb_array_elements(p->'themes_after') t;
 UPDATE public.leyes SET fecha_publicacion=(p->>'date_after')::date WHERE id=lid;
 
 IF (SELECT count(*) FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'after') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'after') b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'La comprobación posterior de artículos falló'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'') IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o FTS vacío'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'themes_after') THEN RAISE EXCEPTION 'Índice incompleto'; END IF;
END $repair$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*) FROM public.articulos a WHERE a.ley_id=l.id) AS fragmentos,(SELECT count(*) FROM public.temas t WHERE t.ley_id=l.id) AS temas,l.fecha_publicacion FROM public.leyes l WHERE l.id='552fdbe9-91d1-4c6b-b1d2-4de35ad51f0c';
